.top-actions { position:fixed; right:16px; top:16px; display:flex; gap:8px; }
#reset, #settingsBtn { border:0; border-radius:999px; background:rgba(20,32,24,.72); color:white; height:42px; padding:0 16px; font-weight:800; cursor:pointer; box-shadow:0 4px 16px rgba(0,0,0,.16); backdrop-filter:blur(8px); }
#settingsBtn { width:42px; padding:0; font-size:21px; }
